package org.securemail.client.community600;

import com.google.gson.*;
import org.securemail.client.net.TorTransport;
import org.securemail.client.community.CommunityJson;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import org.securemail.community.protocol600.CommunityWire600;
import org.securemail.protocol.Limits;
import java.io.*;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.security.PrivateKey;
import java.util.*;
import java.util.concurrent.*;

/** Core Community client with per-app proof keys; no account root, TOTP or plaintext mail passwords. */
public final class CommunityClient600 implements AutoCloseable {
    @FunctionalInterface interface Connector {Socket open(String host,int port,TorTransport.SocketObserver observer)throws IOException;}
    private final String onion,communityAudience,identityAudience,capability;private final int port;private final byte[] communityKey,identityKey;private final PrivateKey appKey;private final IdentityProtocol.Capability cap;private final Connector connector;
    private final Set<Socket> active=ConcurrentHashMap.newKeySet();private final Semaphore slots=new Semaphore(2);private final ScheduledExecutorService deadline=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"aegis-community6-deadline");t.setDaemon(true);return t;});private volatile boolean closed;
    public CommunityClient600(String onion,int port,byte[] communityKey,byte[] identityKey,String capability,PrivateKey appKey,TorTransport tor){this(onion,port,communityKey,identityKey,capability,appKey,Objects.requireNonNull(tor)::connectPeer);}
    CommunityClient600(String onion,int port,byte[] communityKey,byte[] identityKey,String capability,PrivateKey appKey,Connector connector){Limits.onion(onion);if(port<1||port>65535)throw new IllegalArgumentException("Port");IdentityProtocol.publicKey(communityKey);IdentityProtocol.publicKey(identityKey);this.onion=onion;this.port=port;this.communityKey=communityKey.clone();this.identityKey=identityKey.clone();communityAudience=IdentityProtocol.id(communityKey);identityAudience=IdentityProtocol.id(identityKey);this.capability=capability;this.cap=IdentityProtocol.decodeCapability(capability);this.appKey=Objects.requireNonNull(appKey);this.connector=connector;if(cap.appId!=IdentityProtocol.App.AEGIS||!IdentityProtocol.verifyCapability(cap,identityKey,System.currentTimeMillis()))throw new IllegalArgumentException("Invalid Core capability");}
    public JsonObject call(String action,JsonObject data)throws Exception {
        JsonObject args=data==null?new JsonObject():data.deepCopy();args.remove("stepUp");JsonObject critical=new JsonObject();
        if(action.equals("admin.critical.request")){String kind=text(args,"kind");JsonElement payload=args.get("payload");if(payload==null||!payload.isJsonObject())throw new IOException("Нет параметров критического действия");String exact=canonical(payload);long time=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();byte[] expected=IdentityProtocol.criticalApproval(identityAudience,cap.accountId,CommunityWire600.criticalOperation(kind),nonce,exact.getBytes(StandardCharsets.UTF_8),time+300000);critical=criticalProof(expected,time,nonce);}
        else if(action.equals("admin.critical.approve")||args.has("requestId")){String id=action.equals("admin.critical.approve")?text(args,"id"):text(args,"requestId");JsonObject get=new JsonObject();get.addProperty("id",id);JsonObject metadata=exchange("community600.critical.get",get,new JsonObject());String operation=text(metadata,"identityOperation"),identityId=text(metadata,"identityRequestId"),payload=text(metadata,"payload");long expires=metadata.get("expires").getAsLong();if(!action.equals("admin.critical.approve")){JsonObject fields=args.deepCopy();fields.remove("requestId");if(!canonical(fields).equals(payload))throw new IOException("Параметры не совпадают с подтверждённой операцией");}String nonce=IdentityProtocol.nonce();long time=System.currentTimeMillis();critical=criticalProof(IdentityProtocol.criticalApproval(identityAudience,cap.accountId,operation,identityId,payload.getBytes(StandardCharsets.UTF_8),expires),time,nonce);}
        return exchange(action,args,critical);
    }
    private JsonObject criticalProof(byte[] expected,long time,String nonce){JsonObject value=new JsonObject();value.addProperty("time",time);value.addProperty("nonce",nonce);value.addProperty("proof",IdentityProtocol.b64(IdentityProtocol.sign(appKey,IdentityProtocol.requestDigest(cap,"admin.execute",IdentityProtocol.digest(expected),time,nonce))));return value;}
    private JsonObject exchange(String action,JsonObject args,JsonObject critical)throws Exception {
        if(closed)throw new IOException("Соединение закрыто");if(!IdentityProtocol.verifyCapability(cap,identityKey,System.currentTimeMillis()))throw new IOException("Сессия истекла");String identityAction=CommunityWire600.identityAction(action);byte[] exactArgs=args.toString().getBytes(StandardCharsets.UTF_8);byte[] operation=CommunityWire600.operation(communityAudience,action,exactArgs);long time=System.currentTimeMillis();String proofNonce=IdentityProtocol.nonce(),nonce=IdentityProtocol.nonce();JsonObject authorization=new JsonObject();authorization.addProperty("capability",capability);authorization.addProperty("time",time);authorization.addProperty("nonce",proofNonce);authorization.addProperty("proof",IdentityProtocol.b64(IdentityProtocol.sign(appKey,IdentityProtocol.requestDigest(cap,identityAction,IdentityProtocol.digest(operation),time,proofNonce))));JsonObject request=new JsonObject();request.addProperty("action",action);request.addProperty("argsJson",args.toString());request.add("authorization",authorization);request.add("criticalProof",critical);request.addProperty("nonce",nonce);byte[] bytes=request.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>CommunityWire600.MAX_BODY)throw new IOException("Запрос слишком велик");if(!slots.tryAcquire())throw new IOException("Дождитесь завершения запроса");Socket[] observed={null};ScheduledFuture<?>[] timeout={null};
        try(Socket socket=connector.open(onion,port,opened->{observed[0]=opened;active.add(opened);if(closed)throw new IOException("Соединение закрыто");timeout[0]=deadline.schedule(()->{try{opened.close();}catch(IOException ignored){}},30,TimeUnit.SECONDS);})){
            socket.setSoTimeout(20000);OutputStream out=socket.getOutputStream();out.write(("POST /community/v6 HTTP/1.1\r\nHost: "+onion+"\r\nContent-Type: application/json\r\nConnection: close\r\nContent-Length: "+bytes.length+"\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(bytes);out.flush();DataInputStream in=new DataInputStream(socket.getInputStream());String status=line(in,1024);if(!status.matches("HTTP/1\\.[01] [1-5][0-9]{2}(?: [\\x20-\\x7e]*)?"))throw new IOException("HTTP Community");Map<String,String>headers=new HashMap<>();boolean end=false;int total=0;for(int n=0;n<32;n++){String row=line(in,4096);total+=row.length();if(total>8192)throw new IOException("Заголовки");if(row.isEmpty()){end=true;break;}int pos=row.indexOf(':');if(pos<1||!row.substring(0,pos).matches("[A-Za-z0-9-]+")||headers.putIfAbsent(row.substring(0,pos).toLowerCase(Locale.ROOT),row.substring(pos+1).strip())!=null)throw new IOException("Заголовки");}String length=headers.getOrDefault("content-length","");if(!end||headers.containsKey("transfer-encoding")||headers.containsKey("content-encoding")||!length.matches("[0-9]{1,8}"))throw new IOException("Формат ответа");int size=Integer.parseInt(length);if(size<2||size>CommunityWire600.MAX_BODY)throw new IOException("Размер ответа");byte[] reply=in.readNBytes(size);try{if(reply.length!=size||!IdentityProtocol.verify(communityKey,CommunityWire600.response(communityAudience,nonce,bytes,reply),IdentityProtocol.unb64(headers.getOrDefault("aegis-signature",""),64)))throw new IOException("Подпись Community не подтверждена");JsonObject document=CommunityJson.parse(reply);JsonElement ok=document.get("ok");if(ok==null||!ok.isJsonPrimitive()||!ok.getAsJsonPrimitive().isBoolean())throw new IOException("Статус Community");if(!ok.getAsBoolean()){String code=document.has("error")?text(document.getAsJsonObject("error"),"code"):"DENIED";throw new IOException("Community: "+code);}if(!status.startsWith("HTTP/1.1 200")&&!status.startsWith("HTTP/1.0 200"))throw new IOException("Статус HTTP");return document.getAsJsonObject("data");}finally{Arrays.fill(reply,(byte)0);}
        }finally{if(timeout[0]!=null)timeout[0].cancel(false);if(observed[0]!=null){active.remove(observed[0]);try{observed[0].close();}catch(IOException ignored){}}Arrays.fill(bytes,(byte)0);slots.release();}
    }
    private static String text(JsonObject o,String name)throws IOException {JsonElement e=o.get(name);if(e==null||!e.isJsonPrimitive()||!e.getAsJsonPrimitive().isString())throw new IOException("Поле Community");return e.getAsString();}
    static String canonical(JsonElement value)throws IOException {return canonical(value,0);}
    private static String canonical(JsonElement value,int depth)throws IOException {if(depth>16)throw new IOException("Вложенность критического действия");if(value==null||value.isJsonNull())return "null";if(value.isJsonArray()){if(value.getAsJsonArray().size()>256)throw new IOException("Размер списка");StringJoiner j=new StringJoiner(",","[","]");for(JsonElement e:value.getAsJsonArray())j.add(canonical(e,depth+1));return bounded(j.toString());}if(value.isJsonObject()){if(value.getAsJsonObject().size()>128)throw new IOException("Размер объекта");TreeMap<String,JsonElement> sorted=new TreeMap<>();value.getAsJsonObject().entrySet().forEach(e->sorted.put(e.getKey(),e.getValue()));StringJoiner j=new StringJoiner(",","{","}");for(var e:sorted.entrySet())j.add(quote(e.getKey())+":"+canonical(e.getValue(),depth+1));return bounded(j.toString());}JsonPrimitive p=value.getAsJsonPrimitive();if(p.isNumber()){try{java.math.BigDecimal number=new java.math.BigDecimal(p.getAsString());if(number.precision()>128||number.scale()< -128||number.scale()>128)throw new IOException("Число");return number.stripTrailingZeros().toPlainString();}catch(NumberFormatException e){throw new IOException("Число",e);}}return p.isString()?quote(p.getAsString()):p.toString();}
    private static String bounded(String value)throws IOException {if(value.length()>65536)throw new IOException("Размер критического действия");return value;}
    private static String quote(String value)throws IOException {for(int i=0;i<value.length();i++){char c=value.charAt(i);if(Character.isHighSurrogate(c)){if(++i>=value.length()||!Character.isLowSurrogate(value.charAt(i)))throw new IOException("Некорректный символ");}else if(Character.isLowSurrogate(c))throw new IOException("Некорректный символ");}StringBuilder b=new StringBuilder("\"");for(char c:value.toCharArray()){switch(c){case '"'->b.append("\\\"");case '\\'->b.append("\\\\");case '\n'->b.append("\\n");case '\r'->b.append("\\r");case '\t'->b.append("\\t");default->{if(c<32)b.append(String.format(Locale.ROOT,"\\u%04x",(int)c));else b.append(c);}}}return b.append('"').toString();}
    private static String line(DataInputStream in,int max)throws IOException {ByteArrayOutputStream b=new ByteArrayOutputStream();for(int i=0;i<max;i++){int c=in.read();if(c<0)throw new EOFException();if(c=='\r'){if(in.read()!='\n')throw new IOException("HTTP framing");return b.toString(StandardCharsets.US_ASCII);}if(c<32||c>126)throw new IOException("HTTP framing");b.write(c);}throw new IOException("HTTP limit");}
    @Override public void close(){closed=true;for(Socket s:active)try{s.close();}catch(IOException ignored){}deadline.shutdownNow();}
}
